package langbench

import (
	"reflect"
	"testing"

	"google.golang.org/protobuf/proto"

	"github.com/geoffmilleraz/fathom/internal/core"
	scippb "github.com/geoffmilleraz/fathom/third_party/scip"
)

// TestSCIPDefsClangMacroGenerated (LB-F80): scip-clang indexes the
// preprocessed translation unit, so libuv's `TEST_IMPL(loop_stop) {` is the
// definition `run_test_loop_stop` reported over the macro's name. A
// definition whose written text at its range is a different identifier than
// its name was generated by a macro: no syntactic extractor can see it, so
// it is marked Generated (left out of L1, ScoreL1's macro-generated
// exclusion, and disclosed). A definition written as named, and another
// producer's, are untouched; a definition repeated by a file compiled in
// two translation units is one.
func TestSCIPDefsClangMacroGenerated(t *testing.T) {
	src := map[string]string{"test/t.c": "static int helper(void) { return 1; }\nTEST_IMPL(loop_stop) {\n  return 0;\n}\n"}
	def := func(sym string, rng ...int32) *scippb.Occurrence {
		return &scippb.Occurrence{Symbol: sym, Range: rng, SymbolRoles: int32(scippb.SymbolRole_Definition)}
	}
	build := func(tool string) []byte {
		idx := &scippb.Index{Metadata: &scippb.Metadata{ToolInfo: &scippb.ToolInfo{Name: tool, Version: "0.4.0"}}, Documents: []*scippb.Document{
			{RelativePath: "test/t.c", Occurrences: []*scippb.Occurrence{
				def("cxx . . $ helper(aaaaaaaaaaaaaaaa).", 0, 11, 17),
				def("cxx . . $ run_test_loop_stop(bbbbbbbbbbbbbbbb).", 1, 0, 9),
				// the file compiled in a second translation unit: indexed twice
				def("cxx . . $ helper(aaaaaaaaaaaaaaaa).", 0, 11, 17),
				def("cxx . . $ run_test_loop_stop(bbbbbbbbbbbbbbbb).", 1, 0, 9),
			}},
		}}
		raw, err := proto.Marshal(idx)
		if err != nil {
			t.Fatal(err)
		}
		return raw
	}
	read := func(path string) []byte { return []byte(src[path]) }

	defs, tool, _, err := SCIPDefs(build("scip-clang"), read)
	if err != nil {
		t.Fatal(err)
	}
	if tool != "scip-clang" {
		t.Fatalf("tool %q", tool)
	}
	want := []OracleDef{
		{Path: "test/t.c", Name: "helper", Line: 1, Kind: "function"},
		{Path: "test/t.c", Name: "run_test_loop_stop", Line: 2, Kind: "function", Generated: true},
	}
	if !reflect.DeepEqual(defs, want) {
		t.Fatalf("scip-clang SCIPDefs =\n%+v\nwant\n%+v", defs, want)
	}

	other, _, _, err := SCIPDefs(build("scip-other"), read)
	if err != nil {
		t.Fatal(err)
	}
	for _, d := range other {
		if d.Generated {
			t.Errorf("another producer's definition %q marked Generated", d.Name)
		}
	}
}

// TestSCIPDefsClangNames (LB-F80): a macro is named by what is written at its
// range (scip-clang's symbol is its location), a nameless struct is the kind
// "anonymous" and not a macro-generated definition, and a union is a union.
func TestSCIPDefsClangNames(t *testing.T) {
	src := "#define UV_MAX 4\nunion uv_u { int a; };\nstruct {\n  int x;\n} s;\n"
	def := func(sym string, rng ...int32) *scippb.Occurrence {
		return &scippb.Occurrence{Symbol: sym, Range: rng, SymbolRoles: int32(scippb.SymbolRole_Definition)}
	}
	idx := &scippb.Index{Metadata: &scippb.Metadata{ToolInfo: &scippb.ToolInfo{Name: "scip-clang", Version: "0.4.0"}}, Documents: []*scippb.Document{
		{RelativePath: "a.c", Occurrences: []*scippb.Occurrence{
			def("cxx . . $ `a.c:1:9`!", 0, 8, 14),
			def("cxx . . $ uv_u#", 1, 6, 10),
			def("cxx . . $ $anonymous_type_0#", 2, 0, 6),
		}},
	}}
	raw, err := proto.Marshal(idx)
	if err != nil {
		t.Fatal(err)
	}
	defs, _, _, err := SCIPDefs(raw, func(string) []byte { return []byte(src) })
	if err != nil {
		t.Fatal(err)
	}
	want := []OracleDef{
		{Path: "a.c", Name: "UV_MAX", Line: 1, Kind: "macro"},
		{Path: "a.c", Name: "uv_u", Line: 2, Kind: "union"},
		{Path: "a.c", Name: "$anonymous_type_0", Line: 3, Kind: "anonymous"},
	}
	if !reflect.DeepEqual(defs, want) {
		t.Fatalf("SCIPDefs =\n%+v\nwant\n%+v", defs, want)
	}
}

// TestScoreSCIPClangCallSites (LB-F80): L2 is call sites written in the
// source. A function-like macro invoked as `ASSERT_OK(x)` is a call to its
// name (scip-clang's symbol for a macro is its location, so the callee is what
// is written); a function passed as a value (`start(cb)`) is no call; and a
// call a macro expansion makes (`abort`, attributed at the macro's name) is
// not written, so no extractor of call sites can find it: both are counted
// unwritten and disclosed. A call written inside a macro's argument
// (`CHECK(g(2), 0)`) is referenced at the macro's name; it is a written call
// when the callee follows on that line.
func TestScoreSCIPClangCallSites(t *testing.T) {
	src := "static void cb(int x) {}\n" + // 0
		"void run(void) {\n" + // 1
		"  ASSERT_OK(f());\n" + // 2
		"  start(cb);\n" + // 3
		"  cb(1);\n" + // 4
		"  int v = LIMIT;\n" + // 5
		"  CHECK(g(2), 0);\n" + // 6
		"}\n" // 7
	idx := &scippb.Index{Metadata: &scippb.Metadata{ToolInfo: &scippb.ToolInfo{Name: "scip-clang", Version: "0.4.0"}},
		Documents: []*scippb.Document{{RelativePath: "m.c", Occurrences: []*scippb.Occurrence{
			scipCallsiteDef("cxx . . $ cb(1111111111111111).", nil, 0, 12, 14),
			scipCallsiteDef("cxx . . $ run(2222222222222222).", nil, 1, 5, 8),
			scipCallsiteRef("cxx . . $ `h.h:3:9`!", 2, 2, 11),               // ASSERT_OK(...): a macro call
			scipCallsiteRef("cxx . . $ f(3333333333333333).", 2, 12, 13),    // f(): a call
			scipCallsiteRef("cxx . . $ abort(4444444444444444).", 2, 2, 11), // the expansion's abort, at the macro's name
			scipCallsiteRef("cxx . . $ start(5555555555555555).", 3, 2, 7),  // start(...): a call
			scipCallsiteRef("cxx . . $ cb(1111111111111111).", 3, 8, 10),    // cb as a value
			scipCallsiteRef("cxx . . $ cb(1111111111111111).", 4, 2, 4),     // cb(1): a call
			scipCallsiteRef("cxx . . $ `h.h:4:9`!", 5, 10, 15),              // LIMIT: an object-like macro
			scipCallsiteRef("cxx . . $ `h.h:5:9`!", 6, 2, 7),                // CHECK(...): a macro call
			scipCallsiteRef("cxx . . $ g(6666666666666666).", 6, 2, 7),      // g(2) inside its argument, at the macro's name
		}}}}
	raw, err := proto.Marshal(idx)
	if err != nil {
		t.Fatal(err)
	}
	nodes := []core.SymbolNode{
		{Service: "s", Name: "cb", Kind: "CFunc", FilePath: "m.c", Line: 1, EndLine: 1},
		{Service: "s", Name: "run", Kind: "CFunc", FilePath: "m.c", Line: 2, EndLine: 8},
	}
	res, err := ScoreSCIPWith(raw, "s", nodes, SCIPOptionsFor("c", func(string) []byte { return []byte(src) }))
	if err != nil {
		t.Fatal(err)
	}
	want := map[CallPair]bool{{"m.c", "run", "ASSERT_OK"}: true, {"m.c", "run", "f"}: true, {"m.c", "run", "start"}: true, {"m.c", "run", "cb"}: true,
		{"m.c", "run", "CHECK"}: true, {"m.c", "run", "g"}: true}
	if !reflect.DeepEqual(res.CallTruth, want) {
		t.Errorf("call truth = %v, want %v", res.CallTruth, want)
	}
	if res.Counts[CntScipCallsUnwritten] != 2 {
		t.Errorf("unwritten = %d, want 2 (abort in the expansion, cb as a value; the object-like LIMIT is no call and is not counted)", res.Counts[CntScipCallsUnwritten])
	}
}

// TestScoreSCIPClangCallSitesCpp (LB-F80): C++'s extractor excludes an
// all-capitals macro invocation, so its truth keeps no call to the macro
// itself, while a call written inside the macro's argument is still a call.
func TestScoreSCIPClangCallSitesCpp(t *testing.T) {
	src := "void run() {\n" + // 0
		"  FMT_ASSERT(g(2), \"x\");\n" + // 1
		"}\n" // 2
	idx := &scippb.Index{Metadata: &scippb.Metadata{ToolInfo: &scippb.ToolInfo{Name: "scip-clang", Version: "0.4.0"}},
		Documents: []*scippb.Document{{RelativePath: "m.cc", Occurrences: []*scippb.Occurrence{
			scipCallsiteDef("cxx . . $ run(2222222222222222).", nil, 0, 5, 8),
			scipCallsiteRef("cxx . . $ `h.h:3:9`!", 1, 2, 12),
			scipCallsiteRef("cxx . . $ g(6666666666666666).", 1, 2, 12),
		}}}}
	raw, err := proto.Marshal(idx)
	if err != nil {
		t.Fatal(err)
	}
	nodes := []core.SymbolNode{{Service: "s", Name: "run", Kind: "CppFunc", FilePath: "m.cc", Line: 1, EndLine: 3}}
	res, err := ScoreSCIPWith(raw, "s", nodes, SCIPOptionsFor("cpp", func(string) []byte { return []byte(src) }))
	if err != nil {
		t.Fatal(err)
	}
	want := map[CallPair]bool{{"m.cc", "run", "g"}: true}
	if !reflect.DeepEqual(res.CallTruth, want) {
		t.Errorf("call truth = %v, want %v", res.CallTruth, want)
	}
}
